    /// <summary>
    /// True when <paramref name="device"/> is the device currently undergoing a firmware update. During
    /// an update the device's serial transport drops and re-enumerates as an expected part of the flash,
    /// and Core owns the reconnect — so the desktop's disconnect-detection paths must leave that device's
    /// connection untouched rather than disposing the Core device Core is reconnecting (issue #738).
    /// </summary>
    /// <remarks>
    /// The firmware flow always drives the exact connected instance, so reference equality is the primary
    /// (and normally sufficient) match. The fallback compares the serial number — a stable hardware
    /// identity — never the display <c>Name</c>, which is a mutable, non-unique user label and could make
    /// an unrelated same-named device's disconnect be wrongly skipped, leaving a zombie connection.
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.IsDeviceBeingUpdated
    private bool IsDeviceBeingUpdated(IStreamingDevice device)
    {
        var updating = DeviceBeingUpdated;
        if (updating == null)
        {
            return false;
        }

        if (ReferenceEquals(updating, device))
        {
            return true;
        }

        return !string.IsNullOrWhiteSpace(updating.DeviceSerialNo)
            && string.Equals(updating.DeviceSerialNo, device.DeviceSerialNo, StringComparison.OrdinalIgnoreCase);
    }

    // @port: Daqifi.Desktop.ConnectionManager.CheckIfSerialDeviceWasRemoved
    private void CheckIfSerialDeviceWasRemoved()
    {
        // Every backend raises the removal event from a thread-pool thread — WMI's EventArrived and
        // the poller's timer callback alike — so nothing here may touch UI-bound state directly.
        // NotifyConnection's change notification runs DaqifiViewModel.UpdateUi synchronously, and
        // that mutates the notification collection the UI is bound to; done off-thread it can throw
        // straight back into the watcher, which would swallow the removal before the worker below is
        // even started. Post rather than Invoke: the reset and the notification raised at the end of
        // this method then run in the order they were queued, and a host with no dispatcher pumping
        // (a headless harness) cannot block the watcher thread.
        Dispatcher.UIThread.Post(() => NotifyConnection = false);

        var bw = new BackgroundWorker();
        bw.DoWork += delegate
        {
            HashSet<string> availableSerialPorts;
            try
            {
                availableSerialPorts = new HashSet<string>(
                    SerialPort.GetPortNames(),
                    StringComparer.OrdinalIgnoreCase);
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex, "Failed to enumerate serial ports after device change.");
                return;
            }

            // ConnectedDevices is a plain List mutated on the UI thread by Connect/Disconnect, so
            // snapshot it there rather than enumerating it from this worker: a concurrent connect
            // would otherwise throw "collection was modified" into BackgroundWorker's swallowing
            // catch and lose the removal entirely. Port enumeration above stays off-thread, which is
            // the part that is actually slow.
            var connectedSerialDevices = Dispatcher.UIThread.Invoke(
                () => ConnectedDevices.OfType<SerialStreamingDevice>().ToList());

            var devicesToRemove = connectedSerialDevices
                .Where(device =>
                    string.IsNullOrWhiteSpace(device.Port?.PortName) ||
                    !availableSerialPorts.Contains(device.Port.PortName))
                .Cast<IStreamingDevice>()
                .ToList();

            foreach (var serialDevice in devicesToRemove)
            {
                Dispatcher.UIThread.Invoke(delegate
                {
                    // The device being flashed drops off the COM port when it reboots mid-update — an
                    // expected part of the flash that Core reconnects itself. Tearing it down here would
                    // dispose the Core device out from under Core's JumpingToApp reconnect and time the
                    // update out (issue #738), so skip it entirely. The reconcile after the update ends
                    // (see ReconcileDeviceAfterUpdate) handles a genuinely-failed reconnect.
                    if (IsDeviceBeingUpdated(serialDevice))
                    {
                        return;
                    }

                    foreach (var channel in serialDevice.DataChannels)
                    {
                        LoggingManager.Instance.Unsubscribe(channel);
                    }

                    Disconnect(serialDevice);

                    // The firmware-update case is now handled by the early-return above, so this
                    // simplifies to the ordinary spontaneous-disconnect notification.
                    if (!NotifyConnection)
                    {
                        NotifyConnection = true;
                    }
                });
            }
        };

        bw.RunWorkerAsync();
    }

    /// <summary>
    /// Checks if a device is already connected by comparing serial numbers.
    /// </summary>
    /// <param name="newDevice">The device to check for duplicates</param>
    /// <returns>A result indicating if the device is a duplicate and which existing device it matches</returns>
    // @port: Daqifi.Desktop.ConnectionManager.CheckForDuplicateDevice
    private DuplicateDeviceCheckResult CheckForDuplicateDevice(IStreamingDevice newDevice)
    {
        // Match on Core's transport-independent DeviceIdentity (issue #752): it compares the serial
        // number first and falls back to the MAC address when the serial is blank — the WiFi path knows
        // a device's MAC before its serial arrives with the first status message, a case the previous
        // serial-only comparison could not detect at all. A serial mismatch is decisive, so the weaker
        // MAC discriminator can never merge two genuinely different units.
        var candidateIdentity = DeviceIdentity.Create(newDevice.DeviceSerialNo, newDevice.MacAddress);

        // With no discriminator at all there is nothing to compare against, so duplicates are undetectable.
        if (candidateIdentity.IsEmpty)
        {
            AppLogger.Instance.Information(
                $"Device {newDevice.Name} has no serial number or MAC address - cannot check for duplicates");
            return new DuplicateDeviceCheckResult { IsDuplicate = false };
        }

        var existingDevice = ConnectedDevices.FirstOrDefault(d =>
            DeviceIdentity.Create(d.DeviceSerialNo, d.MacAddress).Matches(candidateIdentity));

        if (existingDevice != null)
        {
            var newDeviceInterface = newDevice.ConnectionType == ConnectionType.Usb ? "USB" : "WiFi";
            var existingDeviceInterface = existingDevice.ConnectionType == ConnectionType.Usb ? "USB" : "WiFi";
            
            AppLogger.Instance.Information(
                $"Duplicate device detected ({candidateIdentity}): Device already connected via " +
                $"{existingDeviceInterface}, attempted to add via {newDeviceInterface}");
            
            return new DuplicateDeviceCheckResult 
            { 
                IsDuplicate = true, 
                ExistingDevice = existingDevice,
                NewDevice = newDevice,
                NewDeviceInterface = newDeviceInterface,
                ExistingDeviceInterface = existingDeviceInterface
            };
        }

        return new DuplicateDeviceCheckResult { IsDuplicate = false };
    }
}

/// <summary>
/// Result of checking for duplicate devices
/// </summary>
// @port: Daqifi.Desktop.DuplicateDeviceCheckResult
public class DuplicateDeviceCheckResult
{
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.IsDuplicate
    public bool IsDuplicate { get; set; }
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.ExistingDevice
    public IStreamingDevice ExistingDevice { get; set; }
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.NewDevice
    public IStreamingDevice NewDevice { get; set; }
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.NewDeviceInterface
    public string NewDeviceInterface { get; set; }
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.ExistingDeviceInterface
    public string ExistingDeviceInterface { get; set; }
}

/// <summary>
/// Actions that can be taken when a duplicate device is detected
/// </summary>
// @port: Daqifi.Desktop.DuplicateDeviceAction
public enum DuplicateDeviceAction
{
    KeepExisting,
    SwitchToNew,
    Cancel
}

// @port: Daqifi.Desktop.DAQiFiConnectionStatus
public enum DAQiFiConnectionStatus
{
    Disconnected,
    Connecting,
    Connected,
    Error,
    AlreadyConnected
}
